dtsPropsFor.Button:
/** "primary" = filled accent call-to-action (one per screen), "default" = bordered card-colored button. */
  variant?: "default" | "primary";
  onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  disabled?: boolean;
  type?: "button" | "submit" | "reset";
  className?: string;
  style?: React.CSSProperties;
  children?: React.ReactNode;
  /** Any other native <button> attribute is forwarded. */
  [attr: string]: unknown;

dtsPropsFor.Card:
/** Dimmed (opacity 0.5), e.g. a paused habit. */
  inactive?: boolean;
  /** Layout utility from the global stylesheet, e.g. "stack-sm" (vertical) or "row" (space-between). */
  className?: string;
  onClick?: (event: React.MouseEvent<HTMLDivElement>) => void;
  style?: React.CSSProperties;
  children?: React.ReactNode;
  /** Any other native <div> attribute is forwarded. */
  [attr: string]: unknown;

dtsPropsFor.SegmentedControl:
/** Equal-width buttons, left to right. tone colors the selected segment (pos = green, neg = red), accent when omitted. */
  options: { value: string; label: string; tone?: "pos" | "neg" }[];
  /** Selected option value. Nothing is selected when undefined. */
  value?: string;
  onChange: (value: string) => void;

dtsPropsFor.TabBar:
/** Tabs. badge shows a red attention dot after the label. */
  items: { id: string; label: string; badge?: boolean }[];
  /** id of the selected tab (accent color, bold). */
  active: string;
  onSelect: (id: string) => void;

dtsPropsFor.HistoryEntry:
/** One reviewed day from the rating ledger: day is "YYYY-MM-DD", delta is the signed day total, contributions explain it line by line (rendered when the entry is expanded). */
  entry: {
    day: string; rulesetVersion: string; reviewRevision: number;
    ratingBefore: number; delta: number; ratingAfter: number; capped: boolean;
    contributions: {
      source: { kind: "habit"; habitId: string } | { kind: "clean_day" };
      outcome?: "done" | "not_done" | "complied" | "violated" | "not_applicable" | "unknown";
      base: number; streak: number; multiplier: number; points: number;
    }[];
  };
  /** habitId -> display name, used for habit contribution lines. */
  habitNames: Map<string, string>;
